//! What each write command rests on, from the independent reading of its handler (C8-vector-read,
//! `tests/declarations_independent.rs`): of each object it acts on, of what a group it acts on
//! holds, of the member's root, parent and stack, of the other objects its parameters name, of the
//! layer new art goes into, of the drawing, and of its artboards. [`crate::place::under`] states
//! these as the call's premises. One row per write command, sorted by `id`; a handler change
//! updates its row (and the reading's rows).

/// Fields of an object (`None`: every field).
pub(crate) type Fields = Option<&'static [&'static str]>;

/// Whether where an object is (its parent and index there) matters.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum At {
    /// Not: the command acts on it wherever it is now.
    No,
    /// For the frontmost of the objects only (the result is put where it was).
    Top,
    /// For each of them.
    All,
}

/// Every object of the drawing a document-wide command reads.
pub(crate) struct All {
    pub objects: Fields,
    /// Of type (its characters and styles are in `data`).
    pub text: Fields,
    /// Of symbol instances.
    pub instances: Fields,
    /// Of the layers (`None`: nothing of them).
    pub layers: Option<Fields>,
    /// Which objects each layer and group holds.
    pub windows: bool,
    /// Of the slices and export assets (`None`: nothing of them).
    pub slices: Option<Fields>,
}

pub(crate) struct Rest {
    pub id: &'static str,
    /// Of each object it acts on that holds no others.
    pub leaf: Fields,
    pub leaf_at: At,
    /// Of each type object it acts on.
    pub text: Fields,
    /// Of each group, layer, compound path, blend, clip group or envelope it acts on.
    pub group: Fields,
    pub group_at: At,
    /// Of every object such a group holds (`None`: nothing of them).
    pub inside: Option<Fields>,
    /// Which objects each such group, and each group inside it, holds.
    pub windows: bool,
    /// Acting on a member of a compound path, blend or clip group: of the root, and of its other
    /// members (and which members it holds).
    pub root: Option<(Fields, Fields)>,
    /// Which objects the parent of each holds (its stacking among them).
    pub stack: bool,
    /// Of the layer or group holding each.
    pub parent: Option<Fields>,
    /// Other parameters naming objects: the parameter, the fields, whether where it is matters,
    /// and whether what it holds is read as `inside`.
    pub params: &'static [(&'static str, Fields, bool, bool)],
    /// Of the layer new art goes into.
    pub insertion: Option<Fields>,
    /// Of the drawing: its settings (`guides`) and tables (`~swatches`).
    pub drawing: Fields,
    pub all: Option<All>,
    /// The named entries what it acts on refers to (`swatch`: the global swatches its paint
    /// links; `symbol`: an instance's symbol; `graphicStyle`: the style it is linked to;
    /// `pattern`: the pattern being edited).
    pub refs: &'static [&'static str],
    /// Of an artboard a parameter names by index.
    pub board: Fields,
    /// Of the first artboard (a default the command takes), at its index.
    pub first: Option<Fields>,
    /// Of every artboard.
    pub boards: Option<Fields>,
    /// Of the last artboard, at its index (a default placed after it).
    pub last: Option<Fields>,
    /// With `copy`: the copies carry every field of each, put where each is.
    pub copy: bool,
    /// Of every top-level layer but those holding what it acts on (or, acting on nothing, the
    /// layer new art goes into).
    pub layers: Option<Fields>,
    /// Of the art on the artboard a parameter names (moved, copied or rearranged with it).
    pub art: Option<All>,
    /// Of the objects using the entry a name parameter names (linked to the graphic style, the
    /// instances of the symbol), and whether where they are matters.
    pub users: Option<(Fields, bool)>,
    /// Of every type object.
    pub texts: Option<Fields>,
    /// Of the objects bound to the drawing's variables.
    pub bound: Option<Fields>,
    /// Of every export asset, and of the art each crops.
    pub assets: Option<(Fields, Option<Fields>)>,
    /// Of the objects above (`true`) or below (`false`) each it acts on in its parent, and what
    /// they hold.
    pub neighbours: Option<(Fields, bool)>,
    /// Where the named entry is in its table (a duplicate goes after it, a move counts from it).
    pub name_at: bool,
    /// Where the layer new art goes into is (a new layer goes above it).
    pub insertion_at: bool,
    /// Where each object a group it acts on holds is (the bottom one becomes the clipping path).
    pub inside_at: bool,
}

/// The row of `id`, if it is a write command.
pub(crate) fn rest(id: &str) -> Option<&'static Rest> {
    RESTS.binary_search_by(|row| row.id.cmp(id)).ok().and_then(|at| RESTS.get(at))
}

