/// The row of `id` for a call with `params` acting on objects of `kinds` (`leaf`, `text`,
/// `instance`, `group`, `root`, `member`, `layer`, `slice`): the reading of the path those
/// parameters and objects take, else of the path those parameters take (by the parameters given,
/// and the values of those that are a word or a switch), else the command's row, what every path
/// of it rests on.
pub(crate) fn rest_for(id: &str, params: &serde_json::Value, kinds: &[&str]) -> Option<&'static Rest> {
    let signature = signature(params);
    let mut kinds: Vec<&str> = kinds.to_vec();
    kinds.sort_unstable();
    kinds.dedup();
    let mut with_kinds = signature.clone();
    with_kinds.push(format!("@kinds={}", kinds.join(",")));
    with_kinds.sort();
    let find = |wanted: &[String]| {
        VARIANTS
            .iter()
            .find(|(command, keys, _)| *command == id && keys.len() == wanted.len() && keys.iter().zip(wanted).all(|(key, given)| key == given))
            .map(|(_, _, rest)| rest)
    };
    find(&with_kinds).or_else(|| find(&signature)).or_else(|| rest(id))
}

/// The parameters a call gives but its targets (`ids`, `id`), each as its name, or `name=value`
/// for a switch or a word, sorted.
fn signature(params: &serde_json::Value) -> Vec<String> {
    use serde_json::Value;
    let mut out: Vec<String> = params
        .as_object()
        .into_iter()
        .flatten()
        .filter(|(key, _)| !matches!(key.as_str(), "ids" | "id"))
        .map(|(key, value)| match value {
            Value::Bool(on) => format!("{key}={on}"),
            Value::String(word) => format!("{key}={word}"),
            _ => key.clone(),
        })
        .collect();
    out.sort();
    out
}

